module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    // 3. Stimulus & self-checking:
    integer errors = 0;
    integer i, j;

    // Task to check results
    task check_result(input [7:0] exp_s, input exp_ovf);
        begin
            #1; // Allow propagation delay
            if (s !== exp_s || overflow !== exp_ovf) begin
                $display("ERROR: a=%d, b=%d | Got s=%d (exp %d), overflow=%b (exp %b)", 
                         $signed(a), $signed(b), $signed(s), $signed(exp_s), overflow, exp_ovf);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        a = 8'd0;
        b = 8'd0;
        #10;

        // Targeted test vectors covering normal additions, edge cases, and overflows
        // 1. Zero + Zero
        a = 8'sd0;  b = 8'sd0;  check_result(8'sd0, 1'b0);

        // 2. Positive + Positive (No overflow)
        a = 8'sd10; b = 8'sd20; check_result(8'sd30, 1'b0);

        // 3. Positive + Positive (Overflow boundary: max positive + 1)
        a = 8'sd127; b = 8'sd1; check_result(8'sd128, 1'b1); // 127 + 1 = -128 overflow

        // 4. Negative + Negative (No overflow)
        a = -8'sd10; b = -8'sd20; check_result(-8'sd30, 1'b0);

        // 5. Negative + Negative (Overflow boundary: min negative - 1)
        a = -8'sd128; b = -8'sd1; check_result(8'sd127, 1'b1); // -128 - 1 = 127 overflow

        // 6. Positive + Negative (Never overflows)
        a = 8'sd50;  b = -8'sd50; check_result(8'sd0, 1'b0);
        a = 8'sd127; b = -8'sd128; check_result(-8'sd1, 1'b0);

        // 7. Bounded loop for randomized/systematic coverage of small values
        for (i = -16; i <= 15; i = i + 5) begin
            for (j = -16; j <= 15; j = j + 5) begin
                a = i[7:0];
                b = j[7:0];
                // Calculate expected using 9-bit arithmetic to catch overflows correctly
                begin
                    reg [8:0] full_sum;
                    reg       exp_ovf;
                    reg [7:0] exp_s;

                    full_sum = $signed(i[7:0]) + $signed(j[7:0]);
                    exp_s = full_sum[7:0];
                    // Overflow if result sign differs from both inputs' sign when inputs have same sign
                    exp_ovf = (~i[7] & ~j[7] & exp_s[7]) | (i[7] & j[7] & ~exp_s[7]);

                    check_result(exp_s, exp_ovf);
                end
            end
        end

        // Final Status Reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
